def choose_move(observation):
    # Defensive defaults
    x = observation.get("pos_x", 0)
    y = observation.get("pos_y", 0)
    width = observation.get("grid_width", 0)
    height = observation.get("grid_height", 0)

    # Determine a safe center-ish target based on available fields
    # Prefer staying near center if no explicit goals
    target_x = max(0, min(width - 1, int(width / 2)))
    target_y = max(0, min(height - 1, int(height / 2)))

    # Try to move towards target, staying within -1..1 per axis
    dx = 0
    dy = 0

    if x < target_x:
        dx = 1
    elif x > target_x:
        dx = -1
    else:
        dx = 0

    if y < target_y:
        dy = 1
    elif y > target_y:
        dy = -1
    else:
        dy = 0

    # Defensive adjustment if facing edges or obstacles reported
    obstacles = observation.get("obstacles", [])
    if obstacles:
        # If an obstacle is directly in the chosen direction, try to sidestep
        next_x = x + dx
        next_y = y + dy
        blocked = False
        for ox, oy in obstacles:
            if ox == next_x and oy == next_y:
                blocked = True
                break
        if blocked:
            # Try to neutralize by offsetting in a safe direction
            # Prefer horizontal move then vertical
            if dx != 0:
                if (x, y + 1) not in obstacles and y + 1 < height:
                    dy = 1
                elif (x, y - 1) not in obstacles and y - 1 >= 0:
                    dy = -1
                else:
                    dx = 0
            if dx == 0 and dy != 0:
                if (x + 1, y) not in obstacles and x + 1 < width:
                    dx = 1
                elif (x - 1, y) not in obstacles and x - 1 >= 0:
                    dx = -1

    # Ensure moves are within -1,0,1
    dx = -1 if dx < -1 else 1 if dx > 1 else dx
    dy = -1 if dy < -1 else 1 if dy > 1 else dy

    return [dx, dy]

